-- GENERATED by scripts/gen-seed-sql.mjs from data/services.json and
-- data/packages.json. Do not edit by hand; edit the JSON and re-run.
-- Upserts, so it is safe to re-apply after a price change. Requires
-- pk_0004_catalogue_v2.sql (service numbers above 56, package flags).

on conflict (line_id) do update set service_no = excluded.service_no, service_name = excluded.service_name, model = excluded.model,
  price = excluded.price, unit = excluded.unit, days = excluded.days, is_from = excluded.is_from, active = true;

-- Retired lines stay in the table (orders may reference them) but can no longer be ordered.
update public.pk_catalog_lines set active = false
where line_id not in ('p-wa-card', 'p-social-post', 'p-flyer', '28-dfy', 'p-captions', '22-dfy', '23-dfy', '7-cat', '10-dfy', '25-plan', '25-room', '15-dfy', '3-dfy', '1-dfy', '30-dfy', '14-dfy', '14-setup', '51-mo', '35-mo', '49-setup', '49-mo', '36-one', '36-two', 'ag-overseas-mo', '39-mo', '2-dfy', '4-dfy', '6-dfy', '7-one', '11-dfy', '8-dfy', '5-dfy', '13-dfy', 'proj-landing', 'proj-website', 'proj-promo-video', '21-one', '21-both', '24-dfy', '26-dfy', '27-mo', '40-mo', '38-mo', '41-mo', '17-setup', '20-setup', '18-setup', '19-setup', '48-setup', '47-setup', 'ai-listing', 'ai-website', 'ai-wa-bot', 'ai-autopost', 'ai-content', 'ai-lead-routing', 'ai-docs', 'ai-office', 'ai-followup', 'ai-custom', 'ai-crm', 'ai-agency-fw', 'ai-voice', 'ai-dev-fw', '34-dfy', '37-dfy', '42-dfy', '53-dfy', '54-dfy', '55-mo', '52-mo', '56-dfy', '56-setup', '16-one', '16-all', '29-setup', '29-event');

on conflict (id) do update set name = excluded.name, monthly = excluded.monthly, setup = excluded.setup, one_off = excluded.one_off,
  min_months = excluded.min_months, due_days = excluded.due_days, setup_items = excluded.setup_items,
  quote_only = excluded.quote_only, is_from = excluded.is_from, section = excluded.section, active = true;

-- Retired packages stay for existing subscriptions but can no longer be bought.
update public.pk_packages set active = false where id not in ('agent-monthly', 'agent-pro', 'agency-growth', 'project-monthly', 'project-growth', 'developer-partner', 'agency-launch', 'agency-launch-web', 'project-launch', 'project-launch-web');

delete from public.pk_package_allowances where package_id in ('agent-monthly', 'agent-pro', 'agency-growth', 'project-monthly', 'project-growth', 'developer-partner', 'agency-launch', 'agency-launch-web', 'project-launch', 'project-launch-web');
